extern uint8_t gc_ram[0x01800000];          /* defined by hal/mem.c */
extern uint32_t gc_spr_misc[1024];          /* shadow SPRs, recomp/blocks.c */
extern uint16_t gc_sr_shadow[16];           /* segment shadows            */

/* ---- EA→phys 路由 ----
 * 0xE0000000-0xE0003FFF = DBAT3 锁定缓存区（SDK __LCEnable 建立，16KB LC），
 * 不是 MEM1：原 &0x1FFFFFFF 掩码会把它折叠成 0x0，读写直落盘头/异常表。
 * 路由到 phys 0x01800000 起（hal 侧 LC 缓冲），恰走 hal_slow 慢路径。 */
static inline uint32_t g_phys(uint32_t ea) {
    if ((ea & 0xFFFFC000u) == 0xE0000000u) return 0x01800000u + (ea & 0x3FFFu);
    return ea & 0x1FFFFFFFu;
}

/* MMIO 窗口（0x0C000000-0x0CFFFFFF，含 WGPIPE）在 MEM1 数组下标范围内：
 * 必须先判路由，否则 stw 0xCC008000 会静默写进 gc_ram——WGPIPE/PE/VI/PI
 * 全部失联（曾致 GX FIFO 收 0 字节、PE ACK 落空）。 */
static inline int g_is_mmio(uint32_t p) {
    return (p - 0x0C000000u) < 0x01000000u;
}

/* ---- carry / overflow ---- */static inline void g_set_ca(uint32_t c) {
    gc.xer = (gc.xer & ~0x20000000u) | (c ? 0x20000000u : 0u);
}
static inline void g_set_ov(uint32_t o) {
    if (o) { gc.xer |= 0x40000000u | 0x80000000u; }   /* OV + sticky SO */
    else   { gc.xer &= ~0x40000000u; }
}
static inline uint32_t g_ca2(uint32_t a, uint32_t b) {
    return ((uint64_t)a + (uint64_t)b) > 0xFFFFFFFFull;
}
static inline uint32_t g_ca3(uint32_t a, uint32_t b, uint32_t c) {
    return ((uint64_t)a + (uint64_t)b + (uint64_t)(c & 1u)) > 0xFFFFFFFFull;
}
/* overflow of a + b (carry-in never affects OV) */
static inline uint32_t g_ov_add(uint32_t a, uint32_t b, uint32_t r) {
    return ((~(a ^ b)) & (a ^ r)) >> 31;
}
static inline uint32_t g_ov_mul(int32_t a, int32_t b, uint32_t r) {
    return ((int64_t)a * (int64_t)b) != (int64_t)(int32_t)r;
}
static inline uint32_t g_mulw(int32_t a, int32_t b) {
    return (uint32_t)((int64_t)a * (int64_t)b);
}

/* ---- division (no host UB; see docs/lifter.md) ----
 * divw by zero -> 0, no OV; INT_MIN / -1 -> 0x80000000, OV+SO
 */
static inline uint32_t g_divw(int32_t a, int32_t b, uint32_t ov) {
    if (b == 0) { if (ov) g_set_ov(0); return 0u; }
    if (a == (int32_t)0x80000000u && b == -1) {
        if (ov) g_set_ov(1); return 0x80000000u;
    }
    if (ov) g_set_ov(0);
    return (uint32_t)(a / b);
}
static inline uint32_t g_divwu(uint32_t a, uint32_t b, uint32_t ov) {
    if (ov) g_set_ov(0);
    return b ? a / b : 0u;
}

/* ---- CR ---- */
static inline void g_crf(uint32_t n, uint32_t f) {
    uint32_t sh = 28u - 4u * (n & 7u);
    gc.cr = (gc.cr & ~(0xFu << sh)) | ((f & 0xFu) << sh);
}
static inline void g_cr0(uint32_t r) {
    uint32_t f = (r & 0x80000000u) ? 8u : (r ? 4u : 2u);
    if (gc.xer & 0x80000000u) f |= 1u;
    gc.cr = (gc.cr & 0x0FFFFFFFu) | (f << 28);
}
static inline void g_cr1(void) {
    uint32_t f = (gc.fpscr >> 28) & 0xFu;    /* FX FEX VX OX nibble */
    gc.cr = (gc.cr & 0xF0FFFFFFu) | (f << 24);
}

/* ---- rotates / byte swap ---- */
static inline uint32_t g_rotl32(uint32_t a, uint32_t n) {
    n &= 31u;
    return n ? ((a << n) | (a >> (32u - n))) : a;
}
static inline uint32_t g_bsw32(uint32_t v) {
    return ((v & 0xFFu) << 24) | ((v & 0xFF00u) << 8) |
           ((v >> 8) & 0xFF00u) | (v >> 24);
}
static inline uint16_t g_bsw16(uint16_t v) {
    return (uint16_t)((v >> 8) | (v << 8));
}
static inline uint32_t g_clz32(uint32_t v) {
    return v ? (uint32_t)__builtin_clz(v) : 32u;
}

/* ---- memory (BE, fast path inside 24MB MEM1; MMIO 窗口先路由) ---- */
static inline uint8_t g_pread8(uint32_t p) {
    if (g_is_mmio(p)) return hal_mmio_read8(p);
    return p < 0x01800000u ? gc_ram[p] : hal_slow_read8(p);
}
static inline uint16_t g_pread16(uint32_t p) {
    if (g_is_mmio(p)) return hal_mmio_read16(p);
    if (p < 0x017FFFFEu) {
        return (uint16_t)(((uint16_t)gc_ram[p] << 8) | gc_ram[p + 1]);
    }
    return hal_slow_read16(p);
}
static inline uint32_t g_pread32(uint32_t p) {
    if (g_is_mmio(p)) return hal_mmio_read32(p);
    if (p < 0x017FFFFDu) {
        return ((uint32_t)gc_ram[p] << 24) | ((uint32_t)gc_ram[p + 1] << 16) |
               ((uint32_t)gc_ram[p + 2] << 8) | (uint32_t)gc_ram[p + 3];
    }
    return hal_slow_read32(p);
}
static inline uint64_t g_pread64(uint32_t p) {
    return ((uint64_t)g_pread32(p) << 32) | g_pread32((p + 4u) & 0xFFFFFFFFu);
}
static inline void g_pwrite8(uint32_t p, uint8_t v) {
    if (p >= 0x003CF328u && p < 0x003CF330u) gc_watch_note(p, v);   /* 流位置全局字节写 */
    if (p >= 0x00003000u && p < 0x00003040u) gc_watch_note(p, v);   /* 异常表字节写（清零排查） */
    if (p >= 0x003C3410u && p < 0x003C3440u) {                      /* 主线程 ctx 字节写（限流） */
        static unsigned cb_n;
        if (++cb_n <= 100u) gc_watch_note(p, v);
    }
    if (p >= 0x003CFB10u && p < 0x003CFB20u) {                      /* 音频同步标志整段（stb/sth 取证） */
        static unsigned fb8_n;
        if (++fb8_n <= 60u || fb8_n % 2000u == 0u) gc_watch_note(p, v);
    }
    if (g_is_mmio(p)) hal_mmio_write8(p, v);      /* WGPIPE 在 mmio.c 内分流 */
    else if (p < 0x01800000u) gc_ram[p] = v;
    else hal_slow_write8(p, v);
}
static inline void g_pwrite16(uint32_t p, uint16_t v) {
    if (p >= 0x003CC394u && p < 0x003CC3A4u) gc_watch_note(p, v); /* retrace 计数/队列（半字写） */
    if (p == 0x003C3418u) gc_watch_note(p, v);                    /* 主线程 state/attr（sth） */
    if (p == 0x003CFB14u) {                                       /* 音频同步标志半字写 */
        static unsigned fb16_n;
        if (++fb16_n <= 40u || fb16_n % 1000u == 0u) gc_watch_note(p, v);
    }
    if (g_is_mmio(p)) hal_mmio_write16(p, v);     /* WGPIPE 宽度写（stw） */
    else if (p < 0x017FFFFEu) {
        gc_ram[p] = (uint8_t)(v >> 8); gc_ram[p + 1] = (uint8_t)v;
    } else hal_slow_write16(p, v);
}
static inline void g_pwrite32(uint32_t p, uint32_t v) {
    {   /* r91: Lua 结构写监视：GC_LUA_WATCH="lo:hi[,lo2:hi2]"（物理地址，十六进制，
         * 最多两段；例 00c1ec10:00c1ee90,00c1eed8:00c1eee0 = node 向量+表头） */
        static uint32_t lw_lo, lw_hi, lw_lo2, lw_hi2;
        static int lw_armed = -1;
        if (lw_armed < 0) {
            const char *e = getenv("GC_LUA_WATCH");
            lw_armed = e && *e;
            if (lw_armed) {
                lw_hi = lw_hi2 = 0;
                sscanf(e, "%x:%x,%x:%x", &lw_lo, &lw_hi, &lw_lo2, &lw_hi2);
            }
        }
        if (lw_armed && ((p >= lw_lo && p < lw_hi)
                         || (p >= lw_lo2 && p < lw_hi2))) gc_watch_note(p, v);
    }
    if (p == 0x003CFE1Cu || p == 0x003CFE20u) gc_watch_note(p, v);  /* 游戏同步队列 h/t */
    if (p == 0x003CFE9Cu || p == 0x003CFEA0u) gc_watch_note(p, v);  /* VI retrace 队列 h/t */
    if (p == 0x003CFB90u) gc_watch_note(p, v);                      /* 音频帧计数（外层循环等它>0） */
    if (p == 0x003CFBA4u || p == 0x003CFBA8u) gc_watch_note(p, v);  /* 分派树门控（0x802afac4/afad0） */
    if (p == 0x003CFB14u) {                                         /* 音频同步标志采样 */
        static unsigned fb90_seen;
        if (!fb90_seen) { fb90_seen = 1; }                          /* 占位：B90 另行采样 */
        static unsigned fb_n;
        if (++fb_n <= 40u || fb_n % 1000u == 0u) gc_watch_note(p, v);
    }
    if (p == 0x003CFE94u) {                                         /* retraceCount 采样 */
        static unsigned rc_n;
        if (++rc_n % 5000u == 1u) gc_watch_note(p, v);
    }
    if (p == 0x003C341Cu || p == 0x003C3420u || p == 0x003C342Cu
        || p == 0x003C3430u || p == 0x003C3434u)
        gc_watch_note(p, v);                                        /* 主线程 susp/prio/queue/link */
    if (g_is_mmio(p)) hal_mmio_write32(p, v);     /* WGPIPE 宽度写（stw） */
    else if (p < 0x017FFFFDu) {
        gc_ram[p] = (uint8_t)(v >> 24); gc_ram[p + 1] = (uint8_t)(v >> 16);
        gc_ram[p + 2] = (uint8_t)(v >> 8); gc_ram[p + 3] = (uint8_t)v;
    } else hal_slow_write32(p, v);
}
static inline void g_pwrite64(uint32_t p, uint64_t v) {
    if (g_is_mmio(p)) { hal_slow_write64(p, v); return; }         /* WGPIPE stfd 整 8B */
    g_pwrite32(p, (uint32_t)(v >> 32));
    g_pwrite32((p + 4u) & 0xFFFFFFFFu, (uint32_t)v);
}

/* ---- string / multiple ---- */
static inline void g_lmw(uint32_t p, uint32_t rd) {
    for (uint32_t r = rd; r < 32u; r++) { gc.r[r] = g_pread32(p); p += 4u; }
}
static inline void g_stmw(uint32_t p, uint32_t rs) {
    for (uint32_t r = rs; r < 32u; r++) { g_pwrite32(p, gc.r[r]); p += 4u; }
}
static inline void g_lswi(uint32_t p, uint32_t rd, uint32_t nb) {
    uint32_t n = nb ? nb : 32u, reg = rd, bits = 0u, i;
    for (i = 0u; i < n; i++) {
        bits = (bits << 8) | g_pread8((p + i) & 0xFFFFFFFFu);
        if ((i & 3u) == 3u) { gc.r[reg] = bits; reg = (reg + 1u) & 31u; bits = 0u; }
    }
    if (n & 3u) gc.r[reg] = bits << ((4u - (n & 3u)) * 8u);
}
static inline void g_stswi(uint32_t p, uint32_t rs, uint32_t nb) {
    uint32_t n = nb ? nb : 32u, reg = rs, w = gc.r[rs], i;
    for (i = 0u; i < n; i++) {
        if ((i & 3u) == 0u) w = gc.r[reg];
        g_pwrite8((p + i) & 0xFFFFFFFFu, (uint8_t)(w >> (24u - 8u * (i & 3u))));
        if ((i & 3u) == 3u) reg = (reg + 1u) & 31u;
    }
}
static inline void g_lswx(uint32_t p, uint32_t rd, uint32_t n) {
    uint32_t reg = rd, bits = 0u, i;
    for (i = 0u; i < n; i++) {
        bits = (bits << 8) | g_pread8((p + i) & 0xFFFFFFFFu);
        if ((i & 3u) == 3u) { gc.r[reg] = bits; reg = (reg + 1u) & 31u; bits = 0u; }
    }
    if (n & 3u) gc.r[reg] = bits << ((4u - (n & 3u)) * 8u);
}
static inline void g_stswx(uint32_t p, uint32_t rs, uint32_t n) {
    uint32_t reg = rs, w = gc.r[rs], i;
    for (i = 0u; i < n; i++) {
        if ((i & 3u) == 0u) w = gc.r[reg];
        g_pwrite8((p + i) & 0xFFFFFFFFu, (uint8_t)(w >> (24u - 8u * (i & 3u))));
        if ((i & 3u) == 3u) reg = (reg + 1u) & 31u;
    }
}

/* ---- FP bit patterns (no implicit truncation anywhere) ---- */
static inline double g_frd(uint64_t b) { double d; memcpy(&d, &b, 8); return d; }
static inline uint64_t g_fbr(double d) { uint64_t b; memcpy(&b, &d, 8); return b; }
static inline float g_bf32(uint32_t u) { float f; memcpy(&f, &u, 4); return f; }
static inline uint32_t g_f32b(float f) { uint32_t u; memcpy(&u, &f, 4); return u; }
/* Gekko has two 64-bit lanes per FPR. Scalar and paired instructions share
 * the numeric PS0 lane; packed float bits cannot alias a scalar double. */
static inline double g_ps0(unsigned r) { return g_frd(gc.fpr_bits[r]); }
static inline double g_ps1(unsigned r) { return g_frd(gc.fpr_ps1_bits[r]); }
static inline void g_ps_set(unsigned r, double p0, double p1) {
    gc.fpr_bits[r] = g_fbr(p0);
    gc.fpr_ps1_bits[r] = g_fbr(p1);
}
static inline void g_fs_set(unsigned r, float value) {
    uint64_t bits = g_fbr((double)value);
    gc.fpr_bits[r] = bits;
    gc.fpr_ps1_bits[r] = bits;
}

static inline void g_fcmp(uint32_t n, double a, double b) {
    uint32_t f;
    if (a < b) f = 8u;
    else if (a > b) f = 4u;
    else if (a == b) f = 2u;
    else f = 1u;                                  /* unordered -> SO */
    g_crf(n, f);
}

/* fctiw/fctiwz: NaN -> INT32_MIN, overflow clamps (undefined on HW) */
static inline int32_t g_fctiw(double d) {
    if (d != d) return (int32_t)0x80000000;
    if (d >= 2147483647.0) return (int32_t)0x7FFFFFFF;
    if (d <= -2147483648.0) return (int32_t)0x80000000;
    return (int32_t)nearbyint(d);                 /* RN ties-to-even */
}
static inline int32_t g_fctiwz(double d) {
    if (d != d) return (int32_t)0x80000000;
    if (d >= 2147483647.0) return (int32_t)0x7FFFFFFF;
    if (d <= -2147483648.0) return (int32_t)0x80000000;
    return (int32_t)d;
}

/* fres / frsqrte / ps_res / ps_rsqrte: Gekko hardware is a table estimate;
 * host exact arithmetic is used instead (games tolerate; see lifter.md). */
static inline float g_frsqrte(float x) { return 1.0f / sqrtf(x); }

/* ---- GQR quantization ---- */
/* scale is 6 bits; 0..31 -> 2^-n (load) / 2^n (store); 32..63 -> negative */
static inline float g_gqr_ldscale(uint32_t n) {
    int s = (n <= 31u) ? -(int)n : (64 - (int)n);
    return (float)ldexp(1.0, s);
}
static inline float g_gqr_stscale(uint32_t n) {
    int s = (n <= 31u) ? (int)n : ((int)n - 64);
    return (float)ldexp(1.0, s);
}
static inline uint32_t g_gqr_stride(uint32_t gqr) {
    switch (gqr & 7u) {
    case 4u: case 6u: return 1u;
    case 5u: case 7u: return 2u;
    default: return 4u;
    }
}
static inline uint32_t g_qtz(float v, int lo, int hi) {
    if (!(v == v)) return (uint32_t)lo;           /* NaN */
    if (v < (float)lo) return (uint32_t)lo;
    if (v > (float)hi) return (uint32_t)hi;
    return (uint32_t)(int32_t)v;                  /* truncate toward zero */
}

/* ---- timebase: shared HAL CPU-cycle clock, divided by twelve ---- */
static inline uint32_t g_tbl(void) { return (uint32_t)hal_timebase_ticks(); }
static inline uint32_t g_tbu(void) { return (uint32_t)(hal_timebase_ticks() >> 32); }

/* ---- per-block IRQ poll fast path ----
 * Every lifted block starts with hal_irq_poll_cycles(0). The full function is
 * only needed when an interrupt can be delivered (or diagnostics are on); the
 * common path is one volatile load and the poll counter. */
static inline uint32_t g_irq_poll_fast(uint32_t cycles)
{
    if (cycles || hal_irq_fast_pending || !(gc.msr & 0x8000u))
        return hal_irq_poll_cycles(cycles);
    hal_irq_poll_total++;
    return 0;
}
#define hal_irq_poll_cycles(cycles) g_irq_poll_fast(cycles)

#endif /* GC_GEN_PREFIX_H */
